import { SchemaApiJsonPage } from "@/components/schema";
import app from "@/store/app";
import { moduleDisplay, moduleTypes } from "@/types/module";
import ajax from "@/utils/ajax";
import { observer } from 'mobx-react-lite';
import { Message } from "@arco-design/web-react";
import { useEffect, useMemo, useState } from "react";
import FeatchStore from "@/store/featch";
import { getUuid } from "@/utils";
import module from '@/store/module';
import { toJS } from "mobx";
import { useHistory } from "react-router-dom";

const Module = () => {
    const [featch] = useState(() => new FeatchStore());
    const history = useHistory();

    // console.log('featch.options("plugins")', toJS(featch.options("plugins")))

    return (
        <SchemaApiJsonPage
            notPagination
            apijson={{
                tableName: "Module",
                uniqueKey: "id",
                logging: true,
                findParams: {
                    "@order": "sort+",
                    "@column": "id,source,imgUrl,sort,moduleId,name,nickname,pluginId,category,display,updatedAt"
                },
                processTableData: (list: any[]) => {
                    module.setModulesList(list.map((o) => ({ ...o, key: o.moduleId })))
                    return list;
                },
                postParams: () => {
                    const id = getUuid();
                    return {
                        "extraInfo": {},
                        "id": id,
                        "moduleId": id,
                        "platform": app.platform
                    }
                }
            }}
            logProps={{}}
            queryFilterKeys={['name', 'nickname']}
            formFilterKeys={['source', 'pluginId', 'name', 'nickname', 'category', 'display', 'imgUrl']}
            getOperationList={(list, item) => {

                return [
                    {
                        title: "开发",
                        onClick: () => {
                            history.push(`/module/save?moduleId=${item.moduleId}`)
                        }
                    },
                    ...list,
                    {
                        title: "上传",
                        onClick: () => {
                            ajax.post('/publishModule', {
                                id: item.id
                            }).then((res) => {
                                Message.success(`${name} 模块上传成功`);
                            })
                        }
                    },
                ]
            }}
            schema={{
                type: "object",
                properties: {
                    id: { 
                        type: "string",
                        columnProps: {
                            ellipsis: true,
                            width: 180
                        }
                    },
                    "source": {
                        "type": "string",
                        "title": "模块类型",
                        "maxLength": 100,
                        "columnProps": {
                            "ellipsis": true,
                            "width": 100,
                        },
                        "format": "radio",
                        "default": "custom",
                        // "enum": ["custom", "context"]
                        "enum": ["custom"]
                    },
                    "name": {
                        "type": "string",
                        "title": "组件名",
                        "maxLength": 100,
                        "fieldProps": {
                            "placeholder": "请输入组件名",
                        },
                        "show": {
                            "source{}": ["custom", "context"]
                        },
                        "columnProps": {
                            "ellipsis": true,
                            "width": 120,
                        },
                        "formItemProps": {
                            "shouldUpdate": true,
                            "field": "name",
                            rules: [{
                                required: true,
                            }, {
                                match: /[A-Z][A-Za-z0-9]*$/g,
                                message: "当前命名要符合React组件命名规则"
                            }, {
                                validator(value, callback) {
                                    if(module.nameMap.has(value)){
                                        callback("当前组件名称已存在")
                                    }
                                },
                            }]
                        },
                    },
                    "nickname": {
                        "type": "string",
                        "title": "模块名称",
                        "fieldProps": {
                            "placeholder": "请输入模块名称"
                        },
                        "columnProps": {
                            "ellipsis": true,
                            "width": 100,
                        },
                    },
                    "pluginId": {
                        "type": "string",
                        "title": "所属插件",
                        "format": "selector",
                        "fieldProps": {
                            "type": "plugins"
                        },
                        "enum": toJS(featch.options("plugins")),
                        "maxLength": 50,
                        "show": {
                            "source!{}": ["context"]
                        }
                    },
                    "category": {
                        "type": "string",
                        "title": "模块类别",
                        "maxLength": 50,
                        "show": {
                            "source!{}": ["context"]
                        },
                        "default": "General",
                        "enum": Object.keys(moduleTypes).map((k) => ({ label: moduleTypes[k], value: k })),
                    },
                    "display": {
                        "type": "string",
                        "title": "展示类型",
                        "maxLength": 20,
                        "show": {
                            "source!{}": ["context"]
                        },
                        "format": "radio",
                        "enum": Object.keys(moduleDisplay).map((k) => ({ label: moduleDisplay[k], value: k })),
                        "default": "block"
                    },
                    "imgUrl": {
                        "type": "string",
                        "format": "image",
                        "title": "模块图片"
                    },
                    // "platform": {
                    //     "type": "string",
                    //     "format": "radio",
                    //     "enum":["PC", "Taro"]
                    // },
                    "updatedAt": {
                        "type": "string",
                        "title": "更新时间",
                        "columnProps": {
                            "width": 180,
                        }
                    }
                }
            }}
        />
    )
}

export default observer(Module);